mapper.select:
SELECT a.*, CASE WHEN r.id IS NOT NULL THEN true ELSE false END as isRead FROM oa_announcement a LEFT JOIN oa_announcement_read r ON a.announcement_id = r.announcement_id AND r.user_id = #{userId} WHERE a.deleted = '0' AND a.status = '1' AND (a.expire_time IS NULL OR a.expire_time > NOW()) AND ( a.scope_type = 'ALL' OR (a.scope_type = 'DEPT' AND FIND_IN_SET(#{deptId}, REPLACE(a.scope_value, ' ', '')) > 0) OR (a.scope_type = 'ROLE' AND
(
FIND_IN_SET(#{role}, REPLACE(a.scope_value, ' ', '')) > 0
)
1 = 0
) ) ORDER BY a.is_top DESC, a.priority DESC, a.create_time DESC

SELECT DISTINCT u.user_id AS userId, u.user_name AS userName, COALESCE(NULLIF(u.nick_name, ''), u.user_name) AS nickName, d.dept_name AS deptName FROM sys_user u
INNER JOIN sys_user_role ur ON u.user_id = ur.user_id INNER JOIN sys_role r ON ur.role_id = r.role_id
LEFT JOIN sys_dept d ON u.dept_id = d.dept_id WHERE u.deleted = '0' AND u.status = '0'
AND u.tenant_id = #{tenantId}
AND u.dept_id IN
#{scopeValue}
AND r.deleted = '0' AND r.status = '0'
AND ur.tenant_id = #{tenantId} AND r.tenant_id = #{tenantId}
AND r.role_key IN
#{scopeValue}
ORDER BY u.user_id ASC
